import {searchCharacters, getCharacterById} from './BangumiRequest.js';
import React, {useState, useRef} from 'react';
import debounce from 'lodash.debounce';
import styles from './styles/InputStyles.module.css';
function GuassingCharacter() {
    const [inputTerm, setSearchTerm] = useState('');
    const [results, setResults] = useState([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = React.useRef(null);
    const debouncedSearch =  debounce(async (searchTerm) => {
        if(!searchTerm){
            setResults(["未找到结果"]);
            return ;
        }
        setIsLoading(true);
        try{
            const response = await searchCharacters(searchTerm);
            setResults(response);
            setIsOpen(true);
        }catch(error){
            console.error("Error fetching characters:",error);
        }finally{
            setIsLoading(false);
        }
    },300);
    const handleClick = () => {
        console.log("Button clicked:",inputTerm);
        setSearchTerm(inputTerm);
        debouncedSearch(inputTerm);
    };
    const handleSelect = (item) => {
        const response = getCharacterById(item.id);
        setResults([]);
        setIsOpen(false);
    }
    return (
        <div className = "App">
            <div>
                <h1>猜人物</h1>
            </div>
            <div className = "search-dropdown" ref={dropdownRef}>
                <input type="text" value={inputTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="输入角色名..." className={styles.standardInput}/>
                <button className={styles.buttonstyle} onClick={handleClick} disabled={isLoading}>
                    {isLoading ? '搜索中...' : '搜索'}
                </button>
            </div>
            {isOpen && (<div className = {styles.largeTextarea}>
                {
                    results.length > 0 ? (
                        results.map(item => (
                        <div key={item.id} onClick={()=> handleSelect(item)} className={styles.standardInput}>
                            {item.name}
                        </div>
                        ))
                    ) : (
                        <div className={styles.standardInput}>
                            {isLoading ? '加载中...' : '未找到结果'}
                        </div>
                    )
                }
                </div>
            )}
        </div>
    )
}
export default GuassingCharacter;
